import Sun from '../assets/sun.svg';
import Water from '../assets/water.svg';

function CareScale({ scaleValue, careType }) {
  const scaleType = careType === 'light'
    ? { icon: Sun, label: 'Ensoleillement' }
    : { icon: Water, label: 'Arrosage' };

  const range = [1, 2, 3];

  return (
    <div
      className="care-scale"
      aria-label={`${scaleType.label} : ${scaleValue} sur 3`}
    >
      <span className="care-label">{scaleType.label}</span>
      <div className="care-icons">
        {range.map((rangeElem) =>
          scaleValue >= rangeElem ? (
            <img
              key={rangeElem}
              src={scaleType.icon}
              alt=""
              title={scaleType.label}
              className="care-icon"
            />
          ) : null
        )}
      </div>
    </div>
  );
}

export default CareScale;
